final class Streams {
    var stdout = "", writes = 0, outputs: [OutputStream] = [], inputs: [InputStream] = []
    func output(_ name: String?, _ append: Bool, _ text: String) {
        guard let name else {
            stdout += text;
            writes += 1;
            return
        }
        if !outputs.contains(where: {
            $0.name == name
        }) {
            outputs.append(OutputStream(name))
        };
        let output = outputs.first {
            $0.name == name
        }!
        if !output.open {
            output.open = true;
            if !append {
                output.text = ""
            }
        };
        output.text += text;
        output.writes += 1
    }
    func getline(_ name: String) -> (Int, String?) {
        if !inputs.contains(where: {
            $0.name == name
        }) {
            inputs.append(InputStream(name))
        };
        let input = inputs.first {
            $0.name == name
        }!
        if !input.open {
            input.lines = readFile(name);
            input.position = 0;
            if input.lines != nil {
                input.open = true;
                input.opened = true
            }
        }
        guard let lines = input.lines else {
            return (-1, nil)
        };
        if input.position == lines.count {
            return (0, nil)
        };
        let line = lines[input.position];
        input.position += 1;
        input.reads += 1;
        return (1, line)
    }
    func close(_ name: String) -> Int {
        var closed = false
        if let output = outputs.first(where: {
            $0.name == name
        }) {
            closed = closed || output.open;
            output.open = false
        }
        if let input = inputs.first(where: {
            $0.name == name
        }) {
            closed = closed || input.open;
            input.open = false
        };
        return closed ? 0 : -1
    }
    func save() {
        try! FileManager.default.createDirectory(atPath: "output", withIntermediateDirectories: true)
        try! stdout.write(toFile: "output/stdout.txt", atomically: true, encoding: .utf8)
        for output in outputs {
            try! output.text.write(toFile: "output/" + output.name, atomically: true, encoding: .utf8)
        }
    }
}

import Foundation
enum Value {
    case number(Int), string(String), numeric(String, Int), uninitialized
    static func whitespace(_ c: Character) -> Bool {
        c == " " || c == "\t" || c == "\n"
    }
    static func input(_ text: String) -> Self {
        let trimmed = text.drop(while: whitespace).reversed().drop(while: whitespace).reversed(), raw = String(trimmed), digits = raw.first == "+" || raw.first == "-" ? String(raw.dropFirst()) : raw
        return !digits.isEmpty && digits.utf8.allSatisfy({
            (48...57).contains($0)
        }) ? .numeric(text, Value.string(text).number) : .string(text)
    }
    var number: Int {
        switch self {
            case .number(let n), .numeric(_, let n): return n
            case .uninitialized: return 0
